    summary = {"versions": [dict(version=k, **stats[k]) for k in vkeys], "respondents": n}
    if n:
        summary["effective_n"] = round(sum(w) ** 2 / sum(x * x for x in w), 2)
        summary["weight_min"] = round(min(w), 2)
        summary["weight_max"] = round(max(w), 2)
    else:
        summary["effective_n"] = summary["weight_min"] = summary["weight_max"] = None

    def opts_of(q):
        return q["bands"] if q["type"] == "age" else q["options"]

    cols = [("total", None, None)]
    for bq in plan["banner"]:
        for o in opts_of(qby[bq]):
            if not o.get("missing"):
                cols.append((f"{bq}:{o['code']}", bq, o["code"]))

    tables = []
    for t in plan["tables"]:
        q = qby[t["question"]]
        qid = q["id"]
        multi = q["type"] == "multi"
        rowsdef = [(str(o["code"]), {o["code"]}) for o in opts_of(q) if not o.get("missing")]
        rowsdef += [(nt["id"], set(nt["codes"])) for nt in t.get("nets", [])]
        scores = {o["code"]: o.get("score") for o in q.get("options", [])}
        outcols = []
        for cid, bq, bc in cols:
            idx = [i for i, r in enumerate(k3)
                   if r["ans"][qid] is not None and (bq is None or r["ans"].get(bq) == bc)]
            wb = sum(w[i] for i in idx)
            vals = {}
            for key, codes in rowsdef:
                if not idx:
                    vals[key] = None
                    continue
                s = 0.0
                for i in idx:
                    a = k3[i]["ans"][qid]
                    if (a & codes) if multi else (a in codes):
                        s += w[i]
                vals[key] = round(100 * s / wb, 2) if wb else None
            if t.get("mean"):
                if idx and wb:
                    vals["mean"] = round(sum(w[i] * scores[k3[i]["ans"][qid]] for i in idx) / wb, 2)
                else:
                    vals["mean"] = None
            outcols.append({"column": cid, "base": len(idx),
                            "weighted_base": round(wb, 2) if idx else 0, "values": vals})
        tables.append({"table": t["id"], "columns": outcols})

    with open(outfile, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


